counter.design:
// Generated by SharpHDL 0.6; explicit bit vectors, single clock.
// clk: rising-edge clock. rst: synchronous active-high reset.
// Stream transfer occurs only when TVALID && TREADY at a rising edge.
// Hold data, keep, last and user stable while valid && !ready.
// Numeric temporaries are explicitly sized to preserve truncation semantics.
module h_Counter(
  input wire clk,
  input wire rst,
  // Unsigned 1-bit input; bit 0 is least significant.
  input wire [0:0] s_enable,
  // Unsigned 8-bit output; bit 0 is least significant.
  output wire [7:0] s_value
);
// State register; synchronous active-high reset value 0; updates at rising clk.
reg [7:0] s_count;
// Operation '+'; result limited to 8 bits. Signed interpretation only for slt/asr/signextend.
wire [7:0] n_add_0;
// Select true operand when condition is 1; false operand otherwise.
wire [7:0] n_mux_1;
assign n_add_0 = s_count + 8'd1;
assign n_mux_1 = s_enable ? n_add_0 : s_count;
assign s_value = s_count;
always @(posedge clk) begin
  if (rst) begin
    s_count <= 8'd0;
  end else begin
    s_count <= n_mux_1;
  end
end
endmodule

counter.testbench:
`timescale 1ns/1ps
module tb;reg clk=0,rst=0;
reg s_enable=0;wire [7:0] s_value;
h_Counter dut(.*);
task tick;begin #2;clk=1;#2;clk=0;end endtask
initial begin rst=1;tick;rst=0;
if(s_value!==0)$fatal(1,"reset");s_enable=1;repeat(3)tick;
if(s_value!==3)$fatal(1,"count");s_enable=0;repeat(2)tick;
if(s_value!==3)$fatal(1,"hold");s_enable=1;tick;
if(s_value!==4)$fatal(1,"resume");
$display("PASS VeriSim counter");$finish;end
initial begin $dumpfile("dump.vcd");$dumpvars(1,tb);end
endmodule

