// Generated by SharpHDL 0.6; explicit bit vectors, single clock.
// clk: rising-edge clock. rst: synchronous active-high reset.
// Stream transfer occurs only when TVALID && TREADY at a rising edge.
// Hold data, keep, last and user stable while valid && !ready.
// Numeric temporaries are explicitly sized to preserve truncation semantics.
module h_Backpressure(
  input wire clk,
  input wire rst,
  // Unsigned token ID [7:0]; the lesson sends 10, 11, 12 in order.
  input wire [7:0] s_direct_in_tdata,
  // direct_in: TKEEP bit i qualifies TDATA byte lane i; transported with each beat.
  input wire [0:0] s_direct_in_tkeep,
  // direct_in: TLAST marks the final beat of a packet; meaningful with TVALID.
  input wire [0:0] s_direct_in_tlast,
  // Token position [1:0]: 0, 1, 2. KEEP is one; LAST marks token 12.
  input wire [1:0] s_direct_in_tuser,
  // direct_in: TVALID; producer offers a beat. Must remain asserted during a stall.
  input wire [0:0] s_direct_in_tvalid,
  // direct_in: TREADY; consumer accepts on rising clk when TVALID is also high. Flows opposite payload.
  output wire [0:0] s_direct_in_tready,
  // Unsigned token ID [7:0]; the lesson sends 10, 11, 12 in order.
  output wire [7:0] s_direct_out_tdata,
  // direct_out: TKEEP bit i qualifies TDATA byte lane i; transported with each beat.
  output wire [0:0] s_direct_out_tkeep,
  // direct_out: TLAST marks the final beat of a packet; meaningful with TVALID.
  output wire [0:0] s_direct_out_tlast,
  // Token position [1:0]: 0, 1, 2. KEEP is one; LAST marks token 12.
  output wire [1:0] s_direct_out_tuser,
  // direct_out: TVALID; producer offers a beat. Must remain asserted during a stall.
  output wire [0:0] s_direct_out_tvalid,
  // direct_out: TREADY; consumer accepts on rising clk when TVALID is also high. Flows opposite payload.
  input wire [0:0] s_direct_out_tready,
  // Unsigned 1-bit output; bit 0 is least significant.
  output wire [0:0] s_direct_accepted,
  // Unsigned 1-bit output; bit 0 is least significant.
  output wire [0:0] s_direct_delivered,
  // Unsigned token ID [7:0]; the lesson sends 10, 11, 12 in order.
  input wire [7:0] s_buffered_in_tdata,
  // buffered_in: TKEEP bit i qualifies TDATA byte lane i; transported with each beat.
  input wire [0:0] s_buffered_in_tkeep,
  // buffered_in: TLAST marks the final beat of a packet; meaningful with TVALID.
  input wire [0:0] s_buffered_in_tlast,
  // Token position [1:0]: 0, 1, 2. KEEP is one; LAST marks token 12.
  input wire [1:0] s_buffered_in_tuser,
  // buffered_in: TVALID; producer offers a beat. Must remain asserted during a stall.
  input wire [0:0] s_buffered_in_tvalid,
  // buffered_in: TREADY; consumer accepts on rising clk when TVALID is also high. Flows opposite payload.
  output wire [0:0] s_buffered_in_tready,
  // Unsigned token ID [7:0]; the lesson sends 10, 11, 12 in order.
  output wire [7:0] s_buffered_out_tdata,
  // buffered_out: TKEEP bit i qualifies TDATA byte lane i; transported with each beat.
  output wire [0:0] s_buffered_out_tkeep,
  // buffered_out: TLAST marks the final beat of a packet; meaningful with TVALID.
  output wire [0:0] s_buffered_out_tlast,
  // Token position [1:0]: 0, 1, 2. KEEP is one; LAST marks token 12.
  output wire [1:0] s_buffered_out_tuser,
  // buffered_out: TVALID; producer offers a beat. Must remain asserted during a stall.
  output wire [0:0] s_buffered_out_tvalid,
  // buffered_out: TREADY; consumer accepts on rising clk when TVALID is also high. Flows opposite payload.
  input wire [0:0] s_buffered_out_tready,
  // Unsigned 1-bit output; bit 0 is least significant.
  output wire [0:0] s_buffered_accepted,
  // Unsigned 1-bit output; bit 0 is least significant.
  output wire [0:0] s_buffered_delivered
