// Unsigned token ID [7:0]; the lesson sends 10, 11, 12 in order.
wire [7:0] s_skid_tdata;
// skid: TKEEP bit i qualifies TDATA byte lane i; transported with each beat.
wire [0:0] s_skid_tkeep;
// skid: TLAST marks the final beat of a packet; meaningful with TVALID.
wire [0:0] s_skid_tlast;
// Token position [1:0]: 0, 1, 2. KEEP is one; LAST marks token 12.
wire [1:0] s_skid_tuser;
// skid: TVALID; producer offers a beat. Must remain asserted during a stall.
wire [0:0] s_skid_tvalid;
// skid: TREADY; consumer accepts on rising clk when TVALID is also high. Flows opposite payload.
wire [0:0] s_skid_tready;
// Packed stream beat: DATA [7:0], KEEP [8:8], LAST [9], USER [11:10]. Output holding register.
reg [11:0] s_skid_head;
// Packed stream beat: DATA [7:0], KEEP [8:8], LAST [9], USER [11:10]. Captures the extra accepted beat when downstream stalls.
reg [11:0] s_skid_spill;
// Head contains a valid beat; reset clears it.
reg [0:0] s_skid_valid;
// Spill occupied. Input ready is its inverse, independent of downstream ready.
reg [0:0] s_skid_spill_valid;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_direct_input_handshake;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_direct_output_handshake;
// Operation '~'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_not_0;
// Extract source bits [7:0], rebase to bit 0.
wire [7:0] n_bits_7_0_1;
// Extract source bits [8:8], rebase to bit 0.
wire [0:0] n_bits_8_8_2;
// Extract source bits [9:9], rebase to bit 0.
wire [0:0] n_bits_9_9_3;
// Extract source bits [11:10], rebase to bit 0.
wire [1:0] n_bits_11_10_4;
// Operation '~'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_not_5;
// Operation '|'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_or_6;
// Operation '|'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_or_7;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_and_8;
// Packed bus: [8:8] = high operand; [7:0] = low operand.
wire [8:0] n_concat_9;
// Packed bus: [9:9] = high operand; [8:0] = low operand.
wire [9:0] n_concat_10;
// Packed stream beat: DATA [7:0], KEEP [8:8], LAST [9], USER [11:10].
wire [11:0] n_concat_11;
// Select true operand when condition is 1; false operand otherwise.
wire [11:0] n_mux_12;
// Select true operand when condition is 1; false operand otherwise.
wire [11:0] n_mux_13;
// Operation '~'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_not_14;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_and_15;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_and_16;
// Select true operand when condition is 1; false operand otherwise.
wire [11:0] n_mux_17;
// Operation '|'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_or_18;
// Select true operand when condition is 1; false operand otherwise.
wire [0:0] n_mux_19;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_and_20;
// Operation '|'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_or_21;
// Select true operand when condition is 1; false operand otherwise.
wire [0:0] n_mux_22;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_buffered_input_handshake;
// Operation '&'; result limited to 1 bits. Signed interpretation only for slt/asr/signextend.
wire [0:0] n_buffered_output_handshake;
assign n_direct_input_handshake = s_direct_in_tvalid & s_direct_in_tready;
assign n_direct_output_handshake = s_direct_out_tvalid & s_direct_out_tready;
assign n_not_0 = ~s_skid_spill_valid;
assign n_bits_7_0_1 = s_skid_head >> 0;
assign n_bits_8_8_2 = s_skid_head >> 8;
assign n_bits_9_9_3 = s_skid_head >> 9;
assign n_bits_11_10_4 = s_skid_head >> 10;
assign n_not_5 = ~s_skid_valid;
assign n_or_6 = n_not_5 | s_skid_tready;
assign n_or_7 = s_skid_spill_valid | s_buffered_in_tvalid;
assign n_and_8 = n_or_6 & n_or_7;
assign n_concat_9 = {s_buffered_in_tkeep, s_buffered_in_tdata};
assign n_concat_10 = {s_buffered_in_tlast, n_concat_9};
assign n_concat_11 = {s_buffered_in_tuser, n_concat_10};
assign n_mux_12 = s_skid_spill_valid ? s_skid_spill : n_concat_11;
assign n_mux_13 = n_and_8 ? n_mux_12 : s_skid_head;
assign n_not_14 = ~n_or_6;
assign n_and_15 = s_buffered_in_tvalid & s_buffered_in_tready;
assign n_and_16 = n_not_14 & n_and_15;
assign n_mux_17 = n_and_16 ? n_concat_11 : s_skid_spill;
assign n_or_18 = s_skid_spill_valid | s_buffered_in_tvalid;
assign n_mux_19 = n_or_6 ? n_or_18 : s_skid_valid;
assign n_and_20 = s_buffered_in_tvalid & s_buffered_in_tready;
assign n_or_21 = s_skid_spill_valid | n_and_20;
assign n_mux_22 = n_or_6 ? 1'd0 : n_or_21;
assign n_buffered_input_handshake = s_buffered_in_tvalid & s_buffered_in_tready;
assign n_buffered_output_handshake = s_buffered_out_tvalid & s_buffered_out_tready;
assign s_direct_in_tready = s_direct_out_tready;
assign s_direct_out_tdata = s_direct_in_tdata;
assign s_direct_out_tkeep = s_direct_in_tkeep;
assign s_direct_out_tlast = s_direct_in_tlast;
assign s_direct_out_tuser = s_direct_in_tuser;
assign s_direct_out_tvalid = s_direct_in_tvalid;
assign s_direct_accepted = n_direct_input_handshake;
assign s_direct_delivered = n_direct_output_handshake;
assign s_buffered_in_tready = n_not_0;
assign s_buffered_out_tdata = s_skid_tdata;
assign s_buffered_out_tkeep = s_skid_tkeep;
assign s_buffered_out_tlast = s_skid_tlast;
assign s_buffered_out_tuser = s_skid_tuser;
assign s_buffered_out_tvalid = s_skid_tvalid;
assign s_skid_tdata = n_bits_7_0_1;
assign s_skid_tkeep = n_bits_8_8_2;
assign s_skid_tlast = n_bits_9_9_3;
assign s_skid_tuser = n_bits_11_10_4;
assign s_skid_tvalid = s_skid_valid;
assign s_skid_tready = s_buffered_out_tready;
assign s_buffered_accepted = n_buffered_input_handshake;
assign s_buffered_delivered = n_buffered_output_handshake;
always @(posedge clk) begin
  if (rst) begin
    s_skid_head <= 12'd0;
    s_skid_spill <= 12'd0;
    s_skid_valid <= 1'd0;
    s_skid_spill_valid <= 1'd0;
  end else begin
    s_skid_head <= n_mux_13;
    s_skid_spill <= n_mux_17;
    s_skid_valid <= n_mux_19;
    s_skid_spill_valid <= n_mux_22;
  end
end
endmodule

